const launchZipTown:Record<string,string>={'02035':'foxborough','02048':'mansfield','02093':'wrentham','02081':'walpole','02067':'sharon','02760':'north attleborough'};const profitFloorFor=(size:number)=>size===20?175:size===15?145:125;function rateKeyFor(size:number){return size===10?'yard10':size===15?'yard15':size===20?'yard20':null}function servesZip(p:Provider,zip:string){return !!p.serviceArea&&!!launchZipTown[zip]&&p.serviceArea.toLowerCase().includes(launchZipTown[zip])}async function buildIndexingPlan(){const providers=(await db.list<Provider>('providers',{limit:50})).items.filter(p=>p.score==='viable'&&!p.optedOut),entries=[] as Array<{zip:string;town:string;size:number;url:string;routes:number;expectedProfit:number;marginPct:number}>;for(const [zip,town] of Object.entries(launchZipTown)){for(const size of [10,15,20]){const key=rateKeyFor(size),matches=providers.filter(p=>key&&servesZip(p,zip)&&typeof p.rates?.[key as keyof Rates]==='number').sort((a,b)=>Number(a.rates?.[key as keyof Rates])-Number(b.rates?.[key as keyof Rates]));if(!key||matches.length<2)continue;const safeCost=Math.max(Number(matches[0].rates?.[key as keyof Rates]),Number(matches[1].rates?.[key as keyof Rates])),reserve=25,target=Math.max(profitFloorFor(size),Math.ceil(safeCost*.22)),price=Math.ceil((safeCost+reserve+target)/.97/10)*10,processing=Math.ceil(price*.03),profit=price-safeCost-processing-reserve,marginPct=Math.round(profit/price*100);if(profit<profitFloorFor(size)||marginPct<18)continue;entries.push({zip,town,size,url:`https://marginmatch.net/dumpster-rental-${town.replaceAll(' ','-')}-ma?size=${size}`,routes:matches.length,expectedProfit:profit,marginPct});}}entries.sort((a,b)=>b.expectedProfit-a.expectedProfit||b.routes-a.routes);return{entries,indexed:entries.length,total:Object.keys(launchZipTown).length*3,excluded:Object.keys(launchZipTown).length*3-entries.length,rule:'Only backup-safe lanes meeting the protected profit floor and 18% minimum margin are included in the public sitemap.'};}function economics(r?: Rates) {
  const cost = r?.yard20;
  if (!cost) return { score: 'needs-rate-card', headroom: 0 };
  const retail = 650;
  const processing = Math.ceil(retail * 0.03);
  const reserve = 25;
  const target = 175;
  const headroom = retail - cost - processing - reserve - target;
  return { score: headroom >= 50 ? 'viable' : headroom >= 0 ? 'thin-margin' : 'reject', headroom };
}

